import './TeamChat.css';
import React, { useState } from "react";

const filterMessages = (messages, keyword) => {
  return messages.filter((m) =>
    m.text.toLowerCase().includes(keyword.toLowerCase())
  );
};

const TeamChat = ({ project, user, members }) => {
  const [messages, setMessages] = useState([]);
  const [msg, setMsg] = useState("");
  const [search, setSearch] = useState("");
  const [domainFilter, setDomainFilter] = useState("All");
  const [groupSizeFilter, setGroupSizeFilter] = useState(0);

  const sendMessage = () => {
    if (msg.trim()) {
      const newMessage = {
        sender: user.username,
        text: msg,
        gender: user.gender,
        timestamp: new Date().toLocaleTimeString(),
      };
      setMessages([newMessage, ...messages]);
      setMsg("");
    }
  };

  const filteredMessages = filterMessages(messages, search);

  const filteredMembers = members
    .filter((member) => domainFilter === "All" || member.domain === domainFilter)
    .filter((_, index, arr) => groupSizeFilter === 0 || arr.length <= groupSizeFilter);

  return (
    <div className="team-chat">
      <h3>💬 Team Chat for: <em>{project.title}</em></h3>

      <div className="chat-controls">
        <input
          type="text"
          placeholder="🔍 Search messages..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />

        <select
          value={domainFilter}
          onChange={(e) => setDomainFilter(e.target.value)}
        >
          <option value="All">All Domains</option>
          <option value="Engineering">Engineering</option>
          <option value="Design">Design</option>
          <option value="Marketing">Marketing</option>
          <option value="Sales">Sales</option>
        </select>

        <input
          type="number"
          min="0"
          placeholder="👥 Max Group Size"
          value={groupSizeFilter}
          onChange={(e) => setGroupSizeFilter(Number(e.target.value))}
        />
      </div>

      <div className="chat-box">
        {filteredMessages.length === 0 ? (
          <p>No messages yet.</p>
        ) : (
          filteredMessages.map((m, i) => {
            const isOwnMessage = m.sender === user.username;
            return (
              <div
                key={i}
                className={`chat-msg ${isOwnMessage ? "own-msg" : "other-msg"}`}
              >
                <span><strong>{m.sender}</strong> ({m.gender})</span>
                <span>{m.text}</span>
                <small>{m.timestamp}</small>
              </div>
            );
          })
        )}
      </div>

      <div className="chat-input">
        <input
          type="text"
          value={msg}
          onChange={(e) => setMsg(e.target.value)}
          placeholder="Type your message..."
        />
        <button onClick={sendMessage}>Send</button>
      </div>

      <div className="member-list">
        <h4>👨‍💻 Team Members</h4>
        {filteredMembers.length === 0 ? (
          <p>No members match the filter.</p>
        ) : (
          <ul>
            {filteredMembers.map((member, index) => (
              <li key={index}>
                {member.username} ({member.gender}, {member.domain})
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default TeamChat;
